; gcd.asm - Greatest common divisor of two numbers, by Euclid's subtraction
; algorithm (the SSEM has no hardware divider, so subtraction does the work).
; Put the two numbers on lines 30 and 31; when the machine stops, the gcd is
; on line 28. For example gcd(84, 36) = 12 and gcd(1071, 462) = 21.
;
; This program was generated by AI (model: Mistral Large 4)
;
; Encoding notes:
; - CI is incremented before each fetch, so line 00 is never executed; it is a
;   dummy and execution starts at line 01.
; - JMP/JRP are indirect: JRP S sets CI = CI + store[S]. To land on line T from
;   a JRP on line L, store[S] must be T - L - 1 (CI is incremented again before
;   the next fetch). Lines 25-27 and 29 are those jump-target words.
; - LDN negates on load, so line 24 (T) is also used to flip the sign of the
;   accumulator: STO 24 then LDN 24 negates A.

00 NUM 0     ;
01 LDN 30    ; loop: A = -a
02 STO 24    ;   T = -a
03 LDN 31    ;   A = -b
04 SUB 24    ;   A = a - b  (the difference D)
05 CMP       ;   skip next if D < 0, i.e. a < b
06 JRP 25    ;   a >= b -> line 11
07 STO 24    ; a < b: T = D
08 LDN 24    ;   A = -D = b - a
09 STO 31    ;   b = b - a
10 JRP 26    ;   back to loop (line 1)
11 STO 24    ; a >= b: T = D
12 LDN 24    ;   A = -D
13 CMP       ;   skip next if -D < 0, i.e. D > 0 (a > b)
14 JRP 28    ;   D == 0, i.e. a == b -> done (line 19)
15 STO 24    ; a > b: T = -D
16 LDN 24    ;   A = D
17 STO 30    ;   a = a - b
18 JRP 27    ;   back to loop (line 1)
19 LDN 30    ; done: A = -a
20 STO 24    ;   T = -a
21 LDN 24    ;   A = a (negate again)
22 STO 29    ;   result = a = gcd(a, b)
23 STP
24 NUM 0     ; T: temp, used to negate the accumulator
25 NUM 4     ; jump word for line 06: 11 - 6 - 1
26 NUM -10   ; jump word for line 10: 1 - 10 - 1
27 NUM -18   ; jump word for line 18: 1 - 18 - 1
28 NUM 4     ; jump word for line 14: 19 - 14 - 1
29 NUM 0     ; ---> result: gcd
30 NUM 84    ; <--- a (input)
31 NUM 36    ; <--- b (input)
